	@ParameterizedTest
	@MethodSource("queryShapes")
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void evaluationThatIgnoresTheInterruptAndOutlastsTheTimeLimitReportsIt(QueryShape shape) throws Exception {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		when(repositoryConnection.getRepository().getValueFactory()).thenReturn(values);
		AtomicReference<SingletonIteration<BindingSet>> returned = new AtomicReference<>();
		when(sailConnection.evaluate(any(), any(), any(), anyBoolean())).thenAnswer(invocation -> {
			long until = System.nanoTime()
					+ TimeUnit.MILLISECONDS.toNanos(MAX_EXECUTION_TIME_SECONDS * 1000L + DEADLINE_MARGIN_MILLIS);
			boolean interrupted = false;
			while (System.nanoTime() < until) {
				try {
					Thread.sleep(10);
				} catch (InterruptedException e) {
					interrupted = true;
				}
			}
			if (interrupted) {
				// Code that cannot propagate the InterruptedException restores the flag.
				Thread.currentThread().interrupt();
			}
			MapBindingSet row = new MapBindingSet();
			row.addBinding("subject", values.createIRI("urn:slow:subject"));
			row.addBinding("predicate", values.createIRI("urn:slow:predicate"));
			row.addBinding("object", values.createLiteral("slow"));
			returned.set(new SingletonIteration<>(row));
			return returned.get();
		});
		Callable<Boolean> evaluation = () -> {
			assertThatThrownBy(() -> evaluateAndConsume(shape)).isInstanceOf(QueryInterruptedException.class);
			return Thread.currentThread().isInterrupted();
		};
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try {
			assertThat(executor.submit(evaluation).get(5, TimeUnit.SECONDS))
					.as("the time limit's interrupt must not leak to the caller")
					.isFalse();
			assertThat(returned.get().isClosed()).as("an overdue evaluation result must be closed").isTrue();
		} finally {
			executor.shutdownNow();
			assertThat(executor.awaitTermination(5, TimeUnit.SECONDS)).isTrue();
		}
	}

